```javascript
console.log(add(2, 3)); // 5
function add(a, b) { return a + b; }

const double = (value) => value * 2;

const counter = {
  value: 0,
  increment() { this.value += 1; },
};
counter.increment();
console.log(counter.value, double(4)); // 1 8
